{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Add a small pairwise ranking objective to temperature-0.8 masked-item cross-entropy across all four datasets. Reuse the existing sampled negatives and tied-embedding logits to encourage candidate separation without changing sampling, architecture, inference, or training settings.",
      "edits": [
        {
          "find": "    return torch.nn.functional.cross_entropy(logits / 0.8, targets, reduction=\"mean\")",
          "replace": "    ce_loss = torch.nn.functional.cross_entropy(logits / 0.8, targets, reduction=\"mean\")\n    positive_scores = logits.gather(1, targets.unsqueeze(1)).squeeze(1)\n    negative_targets = neg[mask] - 1\n    negative_scores = logits.gather(1, negative_targets.unsqueeze(1)).squeeze(1)\n    ranking_loss = torch.nn.functional.softplus(\n        (negative_scores - positive_scores) / 0.8\n    ).mean()\n    return ce_loss + 0.05 * ranking_loss"
        }
      ]
    }
  ],
  "change_summary": "Add a 0.05-weighted pairwise softplus loss at masked positions alongside existing cross-entropy. Predictor and checkpoint shapes remain unchanged."
}
